type Status = "learning" | "known" | "review" | "stable";
type ReadingSource = "manual"|"saved"|"annotation"|"builtin"|"ambiguous"|"candidate";
type Entry = { key:string; reading:string; meaning?:string; status:Status; learnedAt:string; lastChecked:string; checks:number; forgot:number; nextReview:string; example:string; streak:number; readingSource?:ReadingSource };
type Book = { id:string; title:string; body:string; createdAt:string; lastRead:string; deletedAt?:string };
type Retention = "7"|"30"|"90"|"never";
type Tab = "home"|"input"|"reading"|"notebook"|"review"|"library"|"history"|"settings";
type KanjiInfo = { literal:string; grade:number; onyomi:string[]; kunyomi:string[]; meanings:string[] };
type ParsedUnit = { text:string; reading?:string; meaning?:string; source?:ReadingSource };

// KANJIDIC由来の常用漢字データから、小学校6学年と中学校相当（grade 8）を採用。
// AI注釈・熟語辞書・手動修正を優先し、それ以外には内蔵漢字辞書から推定読みを付ける。
const SCHOOL_KANJI:Record<string,KanjiInfo> = Object.fromEntries(
  (schoolKanjiData.characters as KanjiInfo[]).map(k=>[k.literal,k])
);
const kataToHira=(s:string)=>s.replace(/[ァ-ヶ]/g,c=>String.fromCharCode(c.charCodeAt(0)-0x60));
const cleanReading=(s:string)=>kataToHira(s.replace(/[.\-]/g,""));
const readingCandidates=(k?:KanjiInfo)=>k?[...new Set([...k.onyomi,...k.kunyomi].map(cleanReading).filter(Boolean))]:[];

const SAMPLE = "[今日|きょう|today]は[学校|がっこう|school]の[図書館|としょかん|library]で[日本|にほん|Japan]の[歴史|れきし|history]について[勉強|べんきょう|studied]しました。[最初|さいしょ|at first]は[難しい|むずかしい|difficult][漢字|かんじ|kanji]が[多い|おおい|many]と[思いました|おもいました|thought]が、[少し|すこし|little by little]ずつ[読める|よめる|became able to read]ようになりました。";
const DICT:Record<string,string> = {
  ...(commonWordsData.words as Record<string,string>),
  // Context-sensitive app overrides take priority over the generated common-word dictionary.
  "今日":"きょう",
};
const WORD_READING_CANDIDATES:Record<string,string[]> = {
  ...(commonWordsData.readingCandidates as Record<string,string[]>),
  // Frequently encountered contextual readings that may not share JMdict's common-word tags.
  "人気":["にんき","ひとけ"],
  "大分":["だいぶ","おおいた"],
};
const BUILTIN_BY_FIRST = Object.entries(DICT).reduce<Record<string,string[]>>((index,[word])=>{
  (index[word[0]]??=[]).push(word);
  return index;
},{});
Object.values(BUILTIN_BY_FIRST).forEach(words=>words.sort((a,b)=>b.length-a.length));
